// P35.51 (K0 §4.12 item 5, NEW-3, ADR-155): the committed lighthouserc*.json are
// GENERATED by scripts/gen-lhci.mjs from dist/page-types.json + page-budgets.json
// — never hand-edited. These tests pin the contract the generation must keep:
// ≥ 1 collect URL per page type (incl. /releases/, a research dossier, an
// entity-shaped page, /sources/, a print page, a T0 record), error-level
// performance assertions per type, measured_gaps rendered as
// [error regression_bound, warn ratified_ceiling] pairs, and the drift gate
// (`check:lhci`) wired into `npm run check`. The byte-for-byte sync itself is
// `npm run check:lhci` after `build` — a drifted committed file fails there.

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { selectUrls } from "../../scripts/gen-lhci.mjs";

const BASE = JSON.parse(readFileSync("lighthouserc.json", "utf-8"));
const NATIONAL = JSON.parse(readFileSync("lighthouserc.national.json", "utf-8"));
const EXPORT_RC = JSON.parse(readFileSync("lighthouserc.export.json", "utf-8"));
const PKG = JSON.parse(readFileSync("package.json", "utf-8"));
const BUDGETS = JSON.parse(readFileSync("tests/e2e/page-budgets.json", "utf-8"));

const blocks = (rc: any) =>
  Object.fromEntries(
    rc.ci.assert.assertMatrix.map((b: any) => [b.matchingUrlPattern, b.assertions]),
  );
const MAP_PATTERN = ".*/map/.*";
const CURATE_PATTERN = ".*/curate/.*";
const blockFor = (rc: any, pattern: string) =>
  rc.ci.assert.assertMatrix.find((b: any) => b.matchingUrlPattern === pattern);

describe("generated lighthouserc files (gen-lhci.mjs)", () => {
  it("carry the GENERATED marker — never a hand-edited file", () => {
    for (const rc of [BASE, NATIONAL, EXPORT_RC]) {
      expect(rc["//"]).toContain("GENERATED by web/scripts/gen-lhci.mjs");
    }
  });

  it("the drift gate is wired: check:lhci is gen-lhci --verify and check runs it", () => {
    expect(PKG.scripts["check:lhci"]).toBe("node scripts/gen-lhci.mjs --verify");
    expect(PKG.scripts.check).toContain("check:lhci");
  });

  it("collects ≥ 1 URL per page type, incl. the contract's named routes (K0 NEW-3)", () => {
    const urls = BASE.ci.collect.url;
    for (const required of [
      "/index.html",
      "/sources/index.html",
      "/releases/index.html",
      "/coverage-metrics/index.html",
      "/data-freshness/index.html",
      "/map/index.html",
      "/network/index.html",
      "/search/index.html",
      "/curate/index.html",
      "/dispute/index.html", // a T0 record surface
    ]) {
      expect(urls, `missing ${required}`).toContain(required);
    }
    expect(urls.some((u: string) => u.includes("print")), "a print page (T0)").toBe(true);
    expect(
      urls.some((u: string) => /research-dossier|dossier\//.test(u)),
      "a research dossier / entity-shaped page",
    ).toBe(true);
  });

  it("asserts error-level performance per type — T0 zero JS, the verbatim §4.3 numbers", () => {
    const t0 = blocks(BASE)['.*/(dispute|print|r|intake)/.*|.*/40[0-9](/|\\.html)|^/r/.*'];
    expect(t0["resource-summary:script:size"]).toEqual([
      "error",
      { maxNumericValue: 0 },
    ]);
    expect(t0["categories:performance"]).toEqual(["error", { minScore: 0.95 }]);
    const map = blockFor(BASE, MAP_PATTERN).assertions;
    expect(map["categories:performance"]).toEqual(["error", { minScore: 0.75 }]);
    expect(map["largest-contentful-paint"]).toEqual([
      "error",
      { maxNumericValue: 2500 },
    ]);
    const t3 = blockFor(BASE, CURATE_PATTERN).assertions;
    expect(t3["categories:accessibility"]).toEqual(["error", { minScore: 1 }]);
    expect(t3["categories:performance"][0]).toBe("warn"); // ADR-068 advisory floor
  });

  it("renders a measured gap as [error bound, warn ratified] — the law is never smoothed", () => {
    const map = blockFor(BASE, MAP_PATTERN).assertions;
    const gap = BUDGETS.measured_gaps.find(
      (g: any) => g.route === "/map/" && g.metric === "jsInitialBytes" && !g.data_source,
    );
    expect(map["resource-summary:script:size"]).toEqual([
      ["error", { maxNumericValue: gap.regression_bound }],
      ["warn", { maxNumericValue: gap.ratified_ceiling }],
    ]);
  });

  it("the national twin collects the same routes and applies the national-scoped gaps", () => {
    expect(NATIONAL.ci.collect.url).toEqual(BASE.ci.collect.url);
    expect(NATIONAL.ci.collect.numberOfRuns).toBe(BASE.ci.collect.numberOfRuns);
    // The national-scoped document gap binds in the twin, not the base file.
    const baseMapDoc = blockFor(BASE, MAP_PATTERN).assertions[
      "resource-summary:document:size"
    ];
    const natMapDoc = blockFor(NATIONAL, MAP_PATTERN).assertions[
      "resource-summary:document:size"
    ];
    const gap = BUDGETS.measured_gaps.find(
      (g: any) =>
        g.route === "/map/" &&
        g.metric === "documentMaxBytes" &&
        g.data_source === "national",
    );
    expect(baseMapDoc).toEqual(["error", { maxNumericValue: gap.ratified_ceiling }]);
    expect(natMapDoc).toEqual([
      ["error", { maxNumericValue: gap.regression_bound }],
      ["warn", { maxNumericValue: gap.ratified_ceiling }],
    ]);
  });

  it("the export twin covers the Round-10 routes + one mounted archive record", () => {
    const urls = EXPORT_RC.ci.collect.url;
    for (const required of [
      "/releases/index.html",
      "/research-dossier/index.html",
      "/r/_fixture-record/index.html",
    ]) {
      expect(urls, `missing ${required}`).toContain(required);
    }
    expect(EXPORT_RC.ci.assert.assertMatrix).toEqual(BASE.ci.assert.assertMatrix);
  });
});

describe("selectUrls — deterministic per-type coverage over discovered routes", () => {
  const manifest = [
    { path: "/", type: "T1" },
    { path: "/dispute/", type: "T0" },
    { path: "/dossier/acme/print/", type: "T0" },
    { path: "/sources/", type: "T1" },
    { path: "/releases/", type: "T1" },
    { path: "/research-dossier/foo/", type: "T1" },
    { path: "/entity/agency-x/", type: "T1" },
    { path: "/map/", type: "T2" },
    { path: "/explore/", type: "T2" },
    { path: "/curate/", type: "T3" },
  ];

  it("picks ≥ 1 route per type and EVERY T2 route, deterministically", () => {
    const a = selectUrls(manifest);
    const b = selectUrls(manifest);
    expect(a).toEqual(b);
    expect(a).toContain("/dispute/");
    expect(a).toContain("/dossier/acme/print/"); // a print page
    expect(a).toContain("/entity/agency-x/"); // an entity-shaped page
    expect(a).toContain("/map/");
    expect(a).toContain("/explore/"); // every T2, not one representative
    expect(a).toContain("/curate/");
    expect(a).toContain("/releases/");
    expect(a).toContain("/research-dossier/foo/");
  });

  it("falls back when a contract route is absent — never emits a dead URL silently", () => {
    const urls = selectUrls(manifest.filter((r) => r.path !== "/dispute/"));
    // A T0 fallback (print page) still covers the type.
    expect(urls.some((u) => u.endsWith("print/"))).toBe(true);
  });
});
